-- ----------------------------
-- Table structure for alert_record
-- ----------------------------
DROP TABLE IF EXISTS `alert_record`;
CREATE TABLE `alert_record` (
  `alert_id` bigint NOT NULL AUTO_INCREMENT COMMENT '告警ID',
  `task_id` bigint NOT NULL COMMENT '任务ID',
  `alert_type` varchar(50) NOT NULL COMMENT '告警类型',
  `alert_level` tinyint NOT NULL COMMENT '告警级别 0=info 1=warning 2=error 3=critical',
  `alert_title` varchar(200) NOT NULL COMMENT '告警标题',
  `alert_message` text COMMENT '告警详细信息',
  `trigger_field` varchar(50) DEFAULT NULL COMMENT '触发字段',
  `trigger_value` varchar(100) DEFAULT NULL COMMENT '触发值',
  `threshold_value` varchar(100) DEFAULT NULL COMMENT '阈值',
  `frame_index` int DEFAULT NULL COMMENT '帧索引',
  `screenshot_url` varchar(500) DEFAULT NULL COMMENT '截图URL',
  `is_handled` tinyint(1) DEFAULT '0' COMMENT '是否已处理',
  `handled_by` bigint DEFAULT NULL COMMENT '处理人ID',
  `handled_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_note` text COMMENT '处理备注',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`alert_id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_alert_level` (`alert_level`),
  KEY `idx_is_handled` (`is_handled`),
  KEY `idx_create_time` (`create_time`),
  CONSTRAINT `fk_alert_task` FOREIGN KEY (`task_id`) REFERENCES `detection_task` (`task_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='告警记录表';

-- ----------------------------
-- Records of alert_record
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for alert_rule
-- ----------------------------
DROP TABLE IF EXISTS `alert_rule`;
CREATE TABLE `alert_rule` (
  `rule_id` bigint NOT NULL AUTO_INCREMENT COMMENT '规则ID',
  `rule_name` varchar(100) NOT NULL COMMENT '规则名称',
  `rule_code` varchar(50) NOT NULL COMMENT '规则代码',
  `rule_type` varchar(50) NOT NULL COMMENT '规则类型 behavior_count/frequency/duration/threshold',
  `class_name` varchar(50) DEFAULT NULL COMMENT '目标类别（为空表示所有类别）',
  `alert_level` tinyint NOT NULL COMMENT '告警级别 0=info 1=warning 2=error 3=critical',
  `threshold_type` varchar(20) NOT NULL COMMENT '阈值类型 count/percentage/duration/frequency',
  `threshold_value` decimal(10,2) NOT NULL COMMENT '阈值',
  `threshold_unit` varchar(20) DEFAULT NULL COMMENT '阈值单位 次/秒/分钟/百分比',
  `time_window_seconds` int DEFAULT NULL COMMENT '时间窗口（秒）',
  `time_window_type` varchar(20) DEFAULT 'frame' COMMENT '时间窗口类型 frame/second/minute/hour',
  `cooldown_seconds` int DEFAULT '60' COMMENT '冷却时间（秒），同一规则重复触发间隔',
  `max_alerts_per_hour` int DEFAULT '10' COMMENT '每小时最大告警次数',
  `alert_title_template` varchar(200) NOT NULL COMMENT '告警标题模板',
  `alert_message_template` text COMMENT '告警消息模板',
  `enable_notification` tinyint(1) DEFAULT '1' COMMENT '是否启用通知',
  `notification_channels` json DEFAULT NULL COMMENT '通知渠道 ["email","sms","websocket"]',
  `save_screenshot` tinyint(1) DEFAULT '1' COMMENT '是否保存截图',
  `screenshot_before_seconds` int DEFAULT '5' COMMENT '告警前截图时长（秒）',
  `auto_handle` tinyint(1) DEFAULT '0' COMMENT '是否自动处理',
  `auto_handle_action` varchar(50) DEFAULT NULL COMMENT '自动处理动作',
  `apply_to_tasks` json DEFAULT NULL COMMENT '应用到的任务ID列表 [1,2,3]',
  `apply_to_devices` json DEFAULT NULL COMMENT '应用到的设备ID列表 [1,2,3]',
  `is_enabled` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `priority` int DEFAULT '5' COMMENT '优先级（1-10）',
  `total_triggered` int DEFAULT '0' COMMENT '总触发次数',
  `last_triggered_time` datetime DEFAULT NULL COMMENT '最后触发时间',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '删除标志',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`rule_id`),
  UNIQUE KEY `uk_rule_code` (`rule_code`),
  KEY `idx_rule_type` (`rule_type`),
  KEY `idx_class_name` (`class_name`),
  KEY `idx_alert_level` (`alert_level`),
  KEY `idx_is_enabled` (`is_enabled`),
  KEY `idx_priority` (`priority`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='告警规则配置表';

-- ----------------------------
-- Records of alert_rule
-- ----------------------------
BEGIN;
